using System.Collections.Generic;

namespace Skynet.Game.AI.Strategy
{
    /// <summary>
    /// An offer made by the server. Index is the response index in that offer,
    /// not a card identifier or a speculative action generated by the policy.
    /// A null-card Activate offer with index -1 represents declining a chain.
    /// </summary>
    public sealed class LegalAction
    {
        public ExecutorType Type { get; private set; }
        public ClientCard Card { get; private set; }
        public int Description { get; private set; }
        public int Index { get; private set; }
        public int Timing { get; private set; }
        public bool IsMandatory { get; private set; }

        public LegalAction(ExecutorType type, ClientCard card, int description, int index, int timing = -1, bool isMandatory = false)
        {
            Type = type;
            Card = card;
            Description = description;
            Index = index;
            Timing = timing;
            IsMandatory = isMandatory;
        }
    }

    public interface IRankedDecisionPolicy
    {
        LegalAction ChooseAction(IList<LegalAction> actions);
        void OnDuelStarted();
        void OnDuelFinished(int result);
    }

    public sealed class ActionEvaluation
    {
        public double Score { get; private set; }
        public IDictionary<string, double> Features { get; private set; }
        public string Reason { get; private set; }

        public ActionEvaluation(double score, IDictionary<string, double> features, string reason = null)
        {
            Score = score;
            Features = features;
            Reason = reason;
        }
    }
}
